{
  "name": "slipi-os",
  "private": true,
  "version": "0.1.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "preview": "vite preview"
  },
  "dependencies": {
    "lucide-react": "^0.468.0",
    "react": "^18.3.1",
    "react-dom": "^18.3.1"
  },
  "devDependencies": {
    "@vitejs/plugin-react": "^4.3.4",
    "vite": "^6.0.5"
  }
}

import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App.jsx';
import './styles.css';

createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
);

import { useEffect, useState } from 'react';
import {
  AppWindow,
  BatteryCharging,
  ChevronDown,
  Command,
  Files,
  Globe2,
  Search,
  Settings2,
  Terminal as TerminalIcon,
  Wifi,
  X,
} from 'lucide-react';

const apps = [
  { id: 'terminal', name: 'Terminal', icon: TerminalIcon, color: 'mint' },
  { id: 'files', name: 'Files', icon: Files, color: 'gold' },
  { id: 'browser', name: 'Browser', icon: Globe2, color: 'blue' },
];

function Clock() {
  const [now, setNow] = useState(() => new Date());

  useEffect(() => {
    const timer = window.setInterval(() => setNow(new Date()), 30_000);
    return () => window.clearInterval(timer);
  }, []);

  return (
    <time dateTime={now.toISOString()}>
      {new Intl.DateTimeFormat(undefined, { weekday: 'short', hour: 'numeric', minute: '2-digit' }).format(now)}
    </time>
  );
}

function AppWindow({ app, onClose }) {
  const Icon = app.icon;

  return (
    <section className="app-window" aria-label={`${app.name} window`}>
      <header className="window-titlebar">
        <div className={`window-app-icon ${app.color}`}><Icon size={15} /></div>
        <span>{app.name}</span>
        <button className="window-close" aria-label={`Close ${app.name}`} onClick={onClose}>
          <X size={15} />
        </button>
      </header>
      {app.id === 'terminal' ? (
        <div className="terminal-body">
          <div className="terminal-session">
            <p className="terminal-kicker">SLIPI / LINUX SESSION</p>
            <div className="runtime-status"><span className="status-dot" /> Runtime not connected</div>
            <p className="terminal-copy">The CheerpX Linux runtime will start here.</p>
            <div className="terminal-prompt"><span>guest@slipi</span><b>:</b><span>~</span><b>$</b><i /></div>
          </div>
          <div className="terminal-footer"><span>UTF-8</span><span>80 × 24</span></div>
        </div>
      ) : (
        <div className="app-empty-state">
          <div className={`empty-icon ${app.color}`}><Icon size={24} /></div>
          <h2>{app.name}</h2>
          <p>This workspace is ready for the next app.</p>
        </div>
      )}
    </section>
  );
}

export default function App() {
  const [activeApp, setActiveApp] = useState('terminal');
  const [launcherOpen, setLauncherOpen] = useState(false);

  const launch = (appId) => {
    setActiveApp(appId);
    setLauncherOpen(false);
  };

  return (
    <main className="desktop">
      <div className="wallpaper-grid" aria-hidden="true" />
      <div className="wallpaper-shape wallpaper-shape-one" aria-hidden="true" />
      <div className="wallpaper-shape wallpaper-shape-two" aria-hidden="true" />

      <header className="topbar">
        <button className="brand-button" onClick={() => setLauncherOpen((open) => !open)} aria-label="Open app launcher">
          <span className="brand-mark"><Command size={15} /></span>
          <span>SlipI</span>
          <ChevronDown size={13} className={launcherOpen ? 'chevron rotated' : 'chevron'} />
        </button>
        <div className="topbar-right">
          <span className="system-label">DESKTOP 01</span>
          <span className="topbar-divider" />
          <Wifi size={15} />
          <BatteryCharging size={16} />
          <Clock />
        </div>
      </header>

      <div className="desktop-label">
        <p>THURSDAY, NOVEMBER 05</p>
        <h1>A clear space<br />to get things done.</h1>
        <span className="desktop-caption">Your web workspace, taking shape.</span>
      </div>

      {activeApp && <AppWindow app={apps.find((app) => app.id === activeApp)} onClose={() => setActiveApp(null)} />}

      {launcherOpen && (
        <section className="launcher" aria-label="Application launcher">
          <div className="launcher-search"><Search size={16} /><span>Find an app</span><kbd>/</kbd></div>
          <p className="launcher-heading">APPLICATIONS</p>
          <div className="launcher-apps">
            {apps.map((app) => {
              const Icon = app.icon;
              return (
                <button key={app.id} className="launcher-app" onClick={() => launch(app.id)}>
                  <span className={`launcher-icon ${app.color}`}><Icon size={19} /></span>
                  <span>{app.name}</span>
                </button>
              );
            })}
            <button className="launcher-app" onClick={() => launch('settings')}>
              <span className="launcher-icon coral"><Settings2 size={19} /></span>
              <span>Settings</span>
            </button>
          </div>
        </section>
      )}

      <nav className="dock" aria-label="Favorite applications">
        {apps.map((app) => {
          const Icon = app.icon;
          return (
            <button key={app.id} className={`dock-app ${activeApp === app.id ? 'is-active' : ''}`} onClick={() => launch(app.id)} aria-label={`Open ${app.name}`} title={app.name}>
              <Icon size={20} />
              {activeApp === app.id && <span className="dock-indicator" />}
            </button>
          );
        })}
        <span className="dock-separator" />
        <button className="dock-app settings-app" onClick={() => launch('settings')} aria-label="Open Settings" title="Settings">
          <Settings2 size={20} />
          {activeApp === 'settings' && <span className="dock-indicator" />}
        </button>
        <span className="dock-spacer" />
        <button className="dock-app launcher-app-button" onClick={() => setLauncherOpen((open) => !open)} aria-label="Show all applications" title="Applications">
          <AppWindow size={19} />
        </button>
      </nav>
      <div className="desktop-edge-note">SLIPI OS <span>·</span> PREVIEW</div>
    </main>
  );
}

@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&display=swap');

:root {
  font-family: 'DM Sans', sans-serif;
  color: #e8eee9;
  background: #101719;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  --ink: #e8eee9;
  --muted: #9aa8a0;
  --line: rgba(224, 239, 230, 0.14);
  --mono: 'DM Mono', monospace;
}

* { box-sizing: border-box; }
body { margin: 0; min-width: 320px; min-height: 100vh; }
button { color: inherit; font: inherit; }

.desktop {
  position: relative;
  width: 100%;
  height: 100vh;
  min-height: 600px;
  overflow: hidden;
  isolation: isolate;
  background: radial-gradient(ellipse at 74% 48%, #253b35 0%, #1b2b29 28%, #152123 59%, #11191c 100%);
}
.desktop::before { position: absolute; z-index: -1; inset: 0; content: ''; background: linear-gradient(118deg, rgba(197, 220, 152, .06), transparent 38%, rgba(32, 70, 61, .12)); }
.wallpaper-grid { position: absolute; z-index: -1; inset: 0; opacity: .16; background-image: linear-gradient(rgba(222, 241, 223, .06) 1px, transparent 1px), linear-gradient(90deg, rgba(222, 241, 223, .06) 1px, transparent 1px); background-size: 64px 64px; mask-image: linear-gradient(90deg, transparent, black 64%, transparent); }
.wallpaper-shape { position: absolute; z-index: -1; border: 1px solid rgba(208, 227, 197, .11); border-radius: 50%; transform: rotate(-31deg); }
.wallpaper-shape-one { width: 750px; height: 300px; top: 24%; left: 29%; box-shadow: 0 0 100px rgba(107, 157, 125, .08), inset 0 0 60px rgba(130, 176, 142, .06); }
.wallpaper-shape-two { width: 970px; height: 480px; top: 14%; left: 23%; border-color: rgba(208, 227, 197, .07); }

.topbar { position: absolute; inset: 0 0 auto; height: 48px; display: flex; align-items: center; justify-content: space-between; padding: 0 26px; border-bottom: 1px solid rgba(230, 239, 230, .09); background: rgba(14, 21, 22, .52); backdrop-filter: blur(18px); }
.brand-button { display: flex; align-items: center; gap: 9px; border: 0; padding: 0; background: none; color: var(--ink); font-size: 13px; font-weight: 700; cursor: pointer; }
.brand-mark { width: 24px; height: 24px; display: grid; place-items: center; color: #17201c; background: #c3d898; border-radius: 7px; }
.chevron { color: #91a096; transition: transform 160ms ease; }.chevron.rotated { transform: rotate(180deg); }
.topbar-right { display: flex; align-items: center; gap: 15px; color: #c6d0c9; font-size: 12px; }
.topbar-right time { min-width: 100px; text-align: right; font-variant-numeric: tabular-nums; }
.system-label, .desktop-label > p, .launcher-heading, .terminal-kicker, .desktop-edge-note { font-family: var(--mono); letter-spacing: 0; }
.system-label { color: #84938a; font-size: 10px; }
.topbar-divider { height: 16px; border-left: 1px solid var(--line); }

.desktop-label { position: absolute; top: 16%; left: 8%; animation: appear 600ms ease both; }
.desktop-label > p { margin: 0 0 18px; color: #a9bd92; font-size: 10px; }
.desktop-label h1 { margin: 0; color: #e5ece3; font-size: clamp(30px, 3.2vw, 46px); line-height: 1.12; font-weight: 500; }
.desktop-caption { display: inline-block; margin-top: 15px; color: #93a29a; font-size: 13px; }

.app-window { position: absolute; z-index: 2; top: 18%; left: 49%; width: min(590px, 52vw); min-width: 390px; height: min(450px, 60vh); min-height: 330px; overflow: hidden; border: 1px solid rgba(229, 239, 230, .22); border-radius: 9px; background: #101719; box-shadow: 0 28px 90px rgba(0, 0, 0, .42), 0 2px 9px rgba(0, 0, 0, .22); animation: window-in 360ms cubic-bezier(.2, .8, .2, 1) both; }
.window-titlebar { height: 43px; display: flex; align-items: center; gap: 10px; padding: 0 13px; border-bottom: 1px solid rgba(222, 235, 225, .1); background: #192122; color: #d7dfd9; font-size: 12px; font-weight: 600; }
.window-app-icon { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 6px; }
.window-close { display: grid; place-items: center; width: 26px; height: 26px; margin-left: auto; padding: 0; border: 0; border-radius: 5px; background: transparent; color: #9eaaa2; cursor: pointer; }
.window-close:hover { background: #ad514b; color: white; }
.terminal-body { height: calc(100% - 43px); display: flex; flex-direction: column; justify-content: space-between; background: #0c1112; color: #d0ddd1; font-family: var(--mono); }
.terminal-session { padding: 28px 29px; }
.terminal-kicker { margin: 0 0 23px; color: #798980; font-size: 9px; }
.runtime-status { display: flex; align-items: center; gap: 8px; color: #b6c4b8; font-size: 11px; }
.status-dot { width: 7px; height: 7px; border-radius: 50%; background: #d69a58; box-shadow: 0 0 10px rgba(214, 154, 88, .3); }
.terminal-copy { margin: 12px 0 0; color: #7e8d83; font-size: 11px; }
.terminal-prompt { display: flex; align-items: center; gap: 6px; margin-top: 40px; font-size: 13px; }
.terminal-prompt span:first-child { color: #b7d38c; }.terminal-prompt b { color: #a9b5ab; font-weight: 400; }.terminal-prompt i { width: 7px; height: 15px; margin-left: 2px; background: #b7d38c; animation: blink 1.2s steps(2, start) infinite; }
.terminal-footer { display: flex; justify-content: space-between; padding: 10px 15px; border-top: 1px solid rgba(222, 235, 225, .08); color: #68766d; font-size: 9px; }
.app-empty-state { height: calc(100% - 43px); display: flex; flex-direction: column; align-items: center; justify-content: center; background: radial-gradient(ellipse at 50% 35%, #202c29, #111819 70%); text-align: center; }
.empty-icon { width: 54px; height: 54px; display: grid; place-items: center; border-radius: 13px; }
.app-empty-state h2 { margin: 17px 0 5px; font-size: 16px; font-weight: 500; }
.app-empty-state p { margin: 0; color: #8e9b92; font-size: 12px; }

.mint { color: #c9dfa1; background: rgba(169, 197, 124, .14); }.gold { color: #e5bd7d; background: rgba(224, 174, 98, .14); }.blue { color: #9cc9ce; background: rgba(109, 174, 179, .14); }.coral { color: #e5a292; background: rgba(208, 119, 98, .14); }

.dock { position: absolute; z-index: 4; left: 50%; bottom: 20px; width: min(440px, calc(100vw - 28px)); height: 58px; display: flex; align-items: center; gap: 7px; padding: 7px 9px; transform: translateX(-50%); border: 1px solid rgba(224, 239, 230, .17); border-radius: 12px; background: rgba(19, 28, 27, .78); box-shadow: 0 12px 44px rgba(0, 0, 0, .26); backdrop-filter: blur(24px); }
.dock-app { position: relative; flex: 0 0 42px; width: 42px; height: 42px; display: grid; place-items: center; padding: 0; border: 1px solid transparent; border-radius: 9px; background: transparent; color: #aab8ad; cursor: pointer; transition: background 130ms ease, color 130ms ease, transform 130ms ease; }
.dock-app:hover { transform: translateY(-3px); background: rgba(222, 239, 224, .1); color: #eff5ed; }
.dock-app.is-active { color: #d5e6b5; background: rgba(196, 221, 150, .13); }
.dock-indicator { position: absolute; bottom: -4px; left: 50%; width: 3px; height: 3px; transform: translateX(-50%); border-radius: 50%; background: #d1e5ab; }
.dock-separator { height: 26px; margin: 0 2px; border-left: 1px solid var(--line); }
.dock-spacer { flex: 1; }
.launcher-app-button { color: #c1ceb9; }
.desktop-edge-note { position: absolute; right: 27px; bottom: 35px; color: #75867b; font-size: 9px; }.desktop-edge-note span { padding: 0 4px; color: #b1c58f; }

.launcher { position: absolute; z-index: 5; top: 58px; left: 20px; width: 320px; padding: 15px; border: 1px solid rgba(224, 239, 230, .16); border-radius: 10px; background: rgba(20, 29, 29, .96); box-shadow: 0 20px 60px rgba(0, 0, 0, .36); backdrop-filter: blur(20px); animation: appear 130ms ease both; }
.launcher-search { height: 37px; display: flex; align-items: center; gap: 9px; padding: 0 10px; border: 1px solid rgba(224, 239, 230, .13); border-radius: 6px; color: #8d9c92; font-size: 12px; }
.launcher-search kbd { margin-left: auto; padding: 2px 5px; border: 1px solid var(--line); border-radius: 3px; color: #93a198; font: 10px var(--mono); }
.launcher-heading { margin: 19px 0 9px; color: #809188; font-size: 9px; }
.launcher-apps { display: grid; grid-template-columns: repeat(2, 1fr); gap: 4px; }
.launcher-app { display: flex; align-items: center; gap: 10px; padding: 8px; border: 0; border-radius: 6px; background: transparent; text-align: left; font-size: 12px; cursor: pointer; }
.launcher-app:hover { background: rgba(220, 236, 218, .08); }
.launcher-icon { width: 32px; height: 32px; display: grid; place-items: center; border-radius: 7px; }

@keyframes blink { to { visibility: hidden; } }
@keyframes appear { from { opacity: 0; transform: translateY(5px); } to { opacity: 1; transform: translateY(0); } }
@keyframes window-in { from { opacity: 0; transform: translateY(9px) scale(.99); } to { opacity: 1; transform: translateY(0) scale(1); } }

@media (max-width: 760px) {
  .desktop { min-height: 520px; }
  .topbar { padding: 0 15px; }
  .topbar-right { gap: 10px; }
  .system-label, .topbar-divider { display: none; }
  .desktop-label { top: 13%; left: 7%; }
  .desktop-label h1 { font-size: 31px; }
  .desktop-caption { font-size: 11px; }
  .app-window { top: 35%; left: 5%; width: 90%; min-width: 0; height: 48%; min-height: 260px; }
  .terminal-session { padding: 22px 19px; }
  .desktop-edge-note { display: none; }
  .dock { bottom: 12px; }
  .launcher { left: 12px; width: min(320px, calc(100vw - 24px)); }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; scroll-behavior: auto !important; transition-duration: .01ms !important; }
}

