import { useEffect, useState } from 'react';
import {
  AppWindow as AppWindowIcon,
  BatteryCharging,
  ChevronDown,
  Command,
  Files,
  Globe2,
  Search,
  Settings2,
  Terminal as TerminalIcon,
  Wifi,
  X,
} from 'lucide-react';

const apps = [
  { id: 'terminal', name: 'Terminal', icon: TerminalIcon, color: 'mint' },
  { id: 'files', name: 'Files', icon: Files, color: 'gold' },
  { id: 'browser', name: 'Browser', icon: Globe2, color: 'blue' },
];
const appRegistry = [...apps, { id: 'settings', name: 'Settings', icon: Settings2, color: 'coral' }];

function Clock() {
  const [now, setNow] = useState(() => new Date());

  useEffect(() => {
    const timer = window.setInterval(() => setNow(new Date()), 30_000);
    return () => window.clearInterval(timer);
  }, []);

  return (
    <time dateTime={now.toISOString()}>
      {new Intl.DateTimeFormat(undefined, { weekday: 'short', hour: 'numeric', minute: '2-digit' }).format(now)}
    </time>
  );
}

function AppWindow({ app, onClose }) {
  const Icon = app.icon;

  return (
    <section className="app-window" aria-label={`${app.name} window`}>
      <header className="window-titlebar">
        <div className={`window-app-icon ${app.color}`}><Icon size={15} /></div>
        <span>{app.name}</span>
        <button className="window-close" aria-label={`Close ${app.name}`} onClick={onClose}>
          <X size={15} />
        </button>
      </header>
