import { useRef, useState } from 'react';
import {
  AppWindow,
  Maximize2,
  Minimize2,
  Minus,
  Plus,
  X,
} from 'lucide-react';

function makeWindow(id, bounds, zIndex) {
  return {
    id,
    title: `Window ${id}`,
    x: bounds.x,
    y: bounds.y,
    width: bounds.width,
    height: bounds.height,
    zIndex,
    minimized: false,
    maximized: false,
    restoreBounds: null,
  };
}

export default function App() {
  const workspaceRef = useRef(null);
  const pointerActionRef = useRef(null);
  const nextIdRef = useRef(2);
  const nextZRef = useRef(2);
  const [windows, setWindows] = useState(() => {
    const width = Math.min(640, window.innerWidth - 40);
    const height = Math.min(420, window.innerHeight - 150);
    return [makeWindow(1, {
      x: Math.max(0, (window.innerWidth - width) / 2),
      y: Math.max(0, (window.innerHeight - height) / 2 - 20),
      width,
      height,
    }, 1)];
  });

  const updateWindow = (id, update) => {
    setWindows((current) => current.map((item) => item.id === id ? { ...item, ...update } : item));
  };

  const focusWindow = (id) => {
    const zIndex = nextZRef.current++;
    updateWindow(id, { zIndex, minimized: false });
  };

  const openWindow = () => {
    const area = workspaceRef.current?.getBoundingClientRect();
    if (!area) return;
    const width = Math.min(580, Math.max(260, area.width - 32));
    const height = Math.min(380, Math.max(220, area.height - 32));
    const offset = (nextIdRef.current - 1) * 24;
    const x = Math.max(0, Math.min((area.width - width) / 2 + offset, area.width - Math.min(width, 120)));
    const y = Math.max(0, Math.min((area.height - height) / 2 + offset, area.height - 44));
    const id = nextIdRef.current++;
    const zIndex = nextZRef.current++;
    setWindows((current) => [...current, makeWindow(id, { x, y, width, height }, zIndex)]);
  };

  const closeWindow = (id) => {
    setWindows((current) => current.filter((item) => item.id !== id));
  };

  const minimizeWindow = (id) => updateWindow(id, { minimized: true });

  const toggleMaximize = (item) => {
    const area = workspaceRef.current?.getBoundingClientRect();
    if (!area) return;
    if (item.maximized) {
      updateWindow(item.id, { ...item.restoreBounds, maximized: false, restoreBounds: null });
      return;
    }
    updateWindow(item.id, {
      restoreBounds: { x: item.x, y: item.y, width: item.width, height: item.height },
      x: 0,
      y: 0,
      width: area.width,
      height: area.height,
      maximized: true,
      minimized: false,
    });
  };

  const startDrag = (event, item) => {
    if (event.button !== 0 || event.target.closest('button') || item.maximized) return;
    focusWindow(item.id);
    pointerActionRef.current = {
      type: 'drag',
      id: item.id,
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      x: item.x,
      y: item.y,
    };
    event.currentTarget.setPointerCapture(event.pointerId);
  };

  const startResize = (event, item) => {
    event.stopPropagation();
    if (event.button !== 0 || item.maximized) return;
    focusWindow(item.id);
    pointerActionRef.current = {
      type: 'resize',
      id: item.id,
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      width: item.width,
      height: item.height,
    };
    event.currentTarget.setPointerCapture(event.pointerId);
  };

  const movePointer = (event) => {
    const action = pointerActionRef.current;
    const area = workspaceRef.current?.getBoundingClientRect();
    if (!action || !area || action.pointerId !== event.pointerId) return;
    if (action.type === 'drag') {
      updateWindow(action.id, {
        x: Math.max(0, Math.min(area.width - 100, action.x + event.clientX - action.startX)),
        y: Math.max(0, Math.min(area.height - 42, action.y + event.clientY - action.startY)),
      });
    } else {
      const current = windows.find((item) => item.id === action.id);
      const minWidth = Math.min(320, area.width);
      const minHeight = Math.min(220, area.height);
      updateWindow(action.id, {
        width: Math.max(minWidth, Math.min(area.width - current.x, action.width + event.clientX - action.startX)),
        height: Math.max(minHeight, Math.min(area.height - current.y, action.height + event.clientY - action.startY)),
      });
    }
  };

  const stopPointer = (event) => {
    if (pointerActionRef.current?.pointerId === event.pointerId) pointerActionRef.current = null;
  };

  return (
