@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&display=swap');

:root {
  font-family: 'DM Sans', sans-serif;
  color: #17241d;
  background: #dce6da;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  --forest: #17251f;
  --moss: #344f3c;
  --lime: #d7ed9f;
  --line: rgba(26, 48, 34, .15);
  --mono: 'DM Mono', monospace;
}

* { box-sizing: border-box; }
html, body, #root { width: 100%; height: 100%; margin: 0; }
body { min-width: 320px; min-height: 420px; overflow: hidden; }
button { font: inherit; }

.desktop { position: relative; width: 100%; height: 100dvh; min-height: 420px; overflow: hidden; background: #dce6da; }
.system-bar { position: absolute; z-index: 20; inset: 0 0 auto; height: 48px; display: flex; align-items: center; justify-content: space-between; padding: 0 20px; color: #f0f3eb; background: var(--forest); }
.system-brand { display: flex; align-items: center; gap: 9px; font-size: 13px; font-weight: 700; }
.brand-symbol { display: grid; width: 25px; height: 25px; place-items: center; border-radius: 6px; color: var(--forest); background: var(--lime); }
.system-status { display: flex; align-items: center; gap: 8px; color: #aab8a9; font: 9px var(--mono); }
.system-status > span:first-child { margin-right: 7px; color: #839587; }
.status-light { width: 6px; height: 6px; border-radius: 50%; background: #b7d77e; box-shadow: 0 0 8px rgba(183, 215, 126, .45); }

.workspace { position: absolute; inset: 48px 0 68px; overflow: hidden; background-color: #dce6da; background-image: linear-gradient(34deg, transparent 63%, rgba(60, 101, 71, .1) 63.1%, transparent 63.3%), linear-gradient(148deg, transparent 72%, rgba(91, 128, 97, .13) 72.1%, transparent 72.3%), linear-gradient(rgba(49, 80, 57, .045) 1px, transparent 1px), linear-gradient(90deg, rgba(49, 80, 57, .045) 1px, transparent 1px); background-size: 100% 100%, 100% 100%, 42px 42px, 42px 42px; }
.wallpaper-mark { position: absolute; top: 50%; left: 50%; display: flex; align-items: center; gap: 16px; transform: translate(-50%, -50%); color: rgba(46, 75, 53, .13); pointer-events: none; user-select: none; }
.wallpaper-mark span { font-size: clamp(56px, 9vw, 128px); line-height: 1; font-weight: 700; letter-spacing: 0; }
.wallpaper-mark i { width: 18px; height: 18px; margin-top: 40px; border-radius: 50%; background: #a1bc83; }

.window { position: absolute; display: flex; flex-direction: column; min-width: min(260px, 100%); min-height: 210px; overflow: hidden; border: 1px solid rgba(21, 43, 29, .28); border-radius: 8px; background: #f7f8f3; box-shadow: 0 18px 50px rgba(30, 50, 35, .2), 0 2px 6px rgba(30, 50, 35, .1); }
.window-hidden { display: none; }
.window-titlebar { flex: 0 0 42px; display: flex; align-items: center; gap: 9px; padding: 0 8px 0 13px; color: #e8eee7; background: #263c30; touch-action: none; user-select: none; cursor: grab; }
.window-titlebar:active { cursor: grabbing; }
.window-app-mark { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 5px; color: #27382b; background: #d2e69b; }
.window-title { overflow: hidden; color: #e5ece4; font-size: 11px; font-weight: 600; text-overflow: ellipsis; white-space: nowrap; }
.window-controls { display: flex; gap: 3px; margin-left: auto; }
.window-controls button { display: grid; width: 27px; height: 27px; place-items: center; border: 0; border-radius: 5px; color: #c4d0c4; background: transparent; cursor: pointer; }
.window-controls button:hover { color: #fff; background: rgba(255, 255, 255, .13); }
.window-controls .close-control:hover { color: #fff; background: #c65e4d; }
.window-content { position: relative; flex: 1; min-height: 0; background: #f7f8f3; }
.content-meta { position: absolute; inset: 14px 16px auto; display: flex; justify-content: space-between; color: #849183; font: 9px var(--mono); }
.content-center { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; color: #647568; font-size: 12px; }
.content-glyph { display: grid; width: 48px; height: 48px; place-items: center; border: 1px solid #d5ded2; border-radius: 13px; color: #47664d; background: #eaf0e5; }
.resize-handle { position: absolute; right: 0; bottom: 0; width: 19px; height: 19px; cursor: nwse-resize; touch-action: none; }
.resize-handle::after { position: absolute; right: 5px; bottom: 5px; width: 7px; height: 7px; border-right: 1px solid #819080; border-bottom: 1px solid #819080; content: ''; }
.window-maximized { border-radius: 6px; }

.taskbar { position: absolute; z-index: 20; inset: auto 0 0; height: 68px; display: flex; align-items: center; gap: 11px; padding: 0 17px; border-top: 1px solid rgba(25, 50, 32, .14); background: rgba(248, 249, 243, .91); backdrop-filter: blur(18px); }
.new-window { display: flex; align-items: center; gap: 8px; height: 38px; padding: 0 12px; border: 0; border-radius: 6px; color: #edf3e6; background: #314c39; font-size: 11px; font-weight: 600; cursor: pointer; }
.new-window:hover { background: #416448; }
.taskbar-divider { height: 26px; border-left: 1px solid var(--line); }
.window-list { display: flex; align-items: center; gap: 5px; min-width: 0; overflow-x: auto; scrollbar-width: none; }
.window-list::-webkit-scrollbar { display: none; }
.taskbar-window { display: flex; align-items: center; gap: 7px; height: 36px; max-width: 160px; padding: 0 10px; border: 1px solid transparent; border-radius: 5px; color: #425747; background: transparent; font-size: 10px; cursor: pointer; }
.taskbar-window span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.taskbar-window:hover { border-color: #d3ddce; background: #edf1e9; }
.taskbar-window.is-minimized { color: #7d8b7b; background: #e7ece3; }
.taskbar-clock { margin-left: auto; color: #7c8b7d; font: 9px var(--mono); white-space: nowrap; }

@media (max-width: 560px) {
  .system-bar { padding: 0 13px; }
  .system-status > span:first-child { display: none; }
  .workspace { inset-bottom: 62px; }
  .taskbar { height: 62px; gap: 7px; padding: 0 9px; }
  .new-window { width: 38px; justify-content: center; padding: 0; }
  .new-window span { display: none; }
  .taskbar-clock { display: none; }
  .window { max-width: 100%; }
}

