const workspace = document.getElementById('workspace');
const windowList = document.getElementById('window-list');
const windows = new Map();
let nextId = 1;
let nextZ = 1;
let pointerAction = null;

function applyBounds(item, bounds) {
  item.x = bounds.x;
  item.y = bounds.y;
  item.width = bounds.width;
  item.height = bounds.height;
  item.element.style.left = `${item.x}px`;
  item.element.style.top = `${item.y}px`;
  item.element.style.width = `${item.width}px`;
  item.element.style.height = `${item.height}px`;
}

function focusWindow(item) {
  item.minimized = false;
  item.element.classList.remove('window-hidden');
  item.taskbarButton.classList.remove('is-minimized');
  item.element.style.zIndex = String(nextZ++);
}

function createWindow() {
  const area = workspace.getBoundingClientRect();
  const width = Math.min(580, Math.max(260, area.width - 32));
  const height = Math.min(380, Math.max(220, area.height - 32));
  const offset = (nextId - 1) * 24;
  const x = Math.max(0, Math.min((area.width - width) / 2 + offset, area.width - Math.min(width, 120)));
  const y = Math.max(0, Math.min((area.height - height) / 2 + offset, area.height - 44));
  const id = nextId++;
  const title = `Window ${id}`;

  const element = document.createElement('section');
  element.className = 'window';
  element.setAttribute('aria-label', title);
  element.innerHTML = `
    <header class="window-titlebar">
      <span class="window-title">${title}</span>
      <div class="window-controls">
        <button type="button" data-action="minimize" aria-label="Minimize ${title}" title="Minimize"><span class="control-icon icon-minimize" aria-hidden="true"></span></button>
        <button type="button" data-action="fullscreen" aria-label="Fullscreen ${title}" title="Fullscreen"><span class="control-icon icon-fullscreen" aria-hidden="true"></span></button>
        <button class="close-control" type="button" data-action="close" aria-label="Close ${title}" title="Close"><span class="control-icon icon-close" aria-hidden="true"></span></button>
      </div>
    </header>
    <div class="window-content">
    </div>
    <div class="resize-handle" role="separator" aria-label="Resize ${title}" tabindex="0"></div>
  `;

  const taskbarButton = document.createElement('button');
  taskbarButton.className = 'taskbar-window';
  taskbarButton.type = 'button';
  taskbarButton.setAttribute('aria-label', `Focus ${title}`);
  taskbarButton.title = title;
  taskbarButton.innerHTML = `<span class="taskbar-window-icon" aria-hidden="true"></span><span>${title}</span>`;
  windowList.append(taskbarButton);
  workspace.append(element);

  const item = { id, title, x, y, width, height, element, taskbarButton, minimized: false, maximized: false, restoreBounds: null };
  windows.set(id, item);
  applyBounds(item, { x, y, width, height });
  element.style.zIndex = String(nextZ++);

  element.addEventListener('pointerdown', () => focusWindow(item));
  element.querySelector('.window-titlebar').addEventListener('pointerdown', (event) => startDrag(event, item));
  element.querySelector('.window-titlebar').addEventListener('pointermove', movePointer);
  element.querySelector('.window-titlebar').addEventListener('pointerup', stopPointer);
  element.querySelector('.window-titlebar').addEventListener('pointercancel', stopPointer);
  element.querySelector('.resize-handle').addEventListener('pointerdown', (event) => startResize(event, item));
  element.querySelector('.resize-handle').addEventListener('pointermove', movePointer);
  element.querySelector('.resize-handle').addEventListener('pointerup', stopPointer);
  element.querySelector('.resize-handle').addEventListener('pointercancel', stopPointer);
  element.querySelector('.window-controls').addEventListener('click', (event) => handleWindowAction(event, item));
  taskbarButton.addEventListener('click', () => focusWindow(item));
}

function handleWindowAction(event, item) {
  const button = event.target.closest('button[data-action]');
  if (!button) return;
  if (button.dataset.action === 'close') {
    item.element.remove();
    item.taskbarButton.remove();
    windows.delete(item.id);
  } else if (button.dataset.action === 'minimize') {
    item.minimized = true;
    item.element.classList.add('window-hidden');
    item.taskbarButton.classList.add('is-minimized');
  } else {
    toggleFullscreen(item, button);
  }
}

function toggleFullscreen(item, button) {
  const area = workspace.getBoundingClientRect();
  if (item.maximized) {
    applyBounds(item, item.restoreBounds);
    item.restoreBounds = null;
    item.maximized = false;
    button.title = 'Fullscreen';
    button.setAttribute('aria-label', `Fullscreen ${item.title}`);
    button.querySelector('.control-icon').className = 'control-icon icon-fullscreen';
    return;
  }
  item.restoreBounds = { x: item.x, y: item.y, width: item.width, height: item.height };
  item.maximized = true;
  item.minimized = false;
  item.element.classList.remove('window-hidden');
  item.taskbarButton.classList.remove('is-minimized');
  applyBounds(item, { x: 0, y: 0, width: area.width, height: area.height });
  button.title = 'Restore';
  button.setAttribute('aria-label', `Restore ${item.title}`);
  button.querySelector('.control-icon').className = 'control-icon icon-restore';
}

function startDrag(event, item) {
  if (event.button !== 0 || event.target.closest('button') || item.maximized) return;
  focusWindow(item);
  pointerAction = { type: 'drag', item, pointerId: event.pointerId, startX: event.clientX, startY: event.clientY, x: item.x, y: item.y };
  event.currentTarget.setPointerCapture(event.pointerId);
}

function startResize(event, item) {
  event.stopPropagation();
  if (event.button !== 0 || item.maximized) return;
  focusWindow(item);
  pointerAction = { type: 'resize', item, pointerId: event.pointerId, startX: event.clientX, startY: event.clientY, width: item.width, height: item.height };
  event.currentTarget.setPointerCapture(event.pointerId);
}

function movePointer(event) {
  const action = pointerAction;
  if (!action || action.pointerId !== event.pointerId) return;
  const area = workspace.getBoundingClientRect();
  if (action.type === 'drag') {
    applyBounds(action.item, {
      x: Math.max(0, Math.min(area.width - 100, action.x + event.clientX - action.startX)),
      y: Math.max(0, Math.min(area.height - 42, action.y + event.clientY - action.startY)),
      width: action.item.width,
      height: action.item.height,
    });
    return;
  }
  const minWidth = Math.min(300, area.width);
  const minHeight = Math.min(210, area.height);
  applyBounds(action.item, {
    x: action.item.x,
    y: action.item.y,
    width: Math.max(minWidth, Math.min(area.width - action.item.x, action.width + event.clientX - action.startX)),
    height: Math.max(minHeight, Math.min(area.height - action.item.y, action.height + event.clientY - action.startY)),
  });
}

function stopPointer(event) {
  if (pointerAction?.pointerId === event.pointerId) pointerAction = null;
}

document.getElementById('new-window').addEventListener('click', createWindow);
window.addEventListener('resize', () => {
  const area = workspace.getBoundingClientRect();
  windows.forEach((item) => {
    if (item.maximized) {
      applyBounds(item, { x: 0, y: 0, width: area.width, height: area.height });
      return;
    }
    const width = Math.min(item.width, area.width);
    const height = Math.min(item.height, area.height);
    applyBounds(item, {
      x: Math.max(0, Math.min(item.x, area.width - 100)),
      y: Math.max(0, Math.min(item.y, area.height - 42)),
      width,
      height,
    });
  });
});

createWindow();

