const h = React.createElement;
const { useEffect, useRef, useState } = React;

function makeWindow(id, area, zIndex) {
  const width = Math.min(580, Math.max(260, area.width - 32));
  const height = Math.min(380, Math.max(220, area.height - 32));
  const offset = (id - 1) * 24;
  return {
    id,
    title: `Window ${id}`,
    x: Math.max(0, Math.min((area.width - width) / 2 + offset, area.width - Math.min(width, 120))),
    y: Math.max(0, Math.min((area.height - height) / 2 + offset, area.height - 44)),
    width,
    height,
    zIndex,
    minimized: false,
    maximized: false,
    restoreBounds: null,
  };
}

function App() {
