    h(ToolButton, { icon: 'folder-new', label: 'New folder', onClick: createFolder }),
    h(ToolButton, { icon: 'document-open', label: 'Import files', onClick: () => filesInput.current.click() }),
    h(ToolButton, { icon: 'folder-new', label: 'Import folder', onClick: () => folderInput.current.click() }),
