      openApp,
      openWindow,
      openFileManager,
      getWindows: () => windowsRef.current.map(({ id, title, x, y, width, height, minimized, maximized }) => ({ id, title, x, y, width, height, minimized, maximized })),
      closeWindow,
      minimizeWindow,
      maximizeWindow: toggleMaximize,
      resizeWindow,
      filesystem: Object.freeze({
        readdir: (path = '/') => fs.promises.readdir(path),
        stat: (path) => fs.promises.stat(path),
        readFile: (path, encoding) => fs.promises.readFile(path, encoding),
        writeFile: (path, data) => fs.promises.writeFile(path, data),
        mkdir: (path, options) => fs.promises.mkdir(path, options),
        rename: (from, to) => fs.promises.rename(from, to),
        remove: (path) => fs.promises.rm(path, { recursive: true, force: true }),
      }),
    };
    return () => { delete window.WebOS; };
  }, []);

  function promptForApp() {
    const source = window.prompt('Application HTML path or URL', 'WebOS filesystem/Applications/api-example/index.html?--is_windowed&--window_size=640x420');
    if (source) openApp(source);
  }

  function controlButton(item, action, icon, label) {
    return h('button', {
      key: action,
      type: 'button',
      className: action === 'close' ? 'close-control' : '',
      title: label,
      'aria-label': `${label} ${item.title}`,
      onPointerDown: (event) => event.stopPropagation(),
