    window.WebOS = {
      openApp,
      openWindow,
      openFileManager,
      getWindows: () => windowsRef.current.map(({ id, title, x, y, width, height, minimized, maximized }) => ({ id, title, x, y, width, height, minimized, maximized })),
      closeWindow,
      minimizeWindow,
      maximizeWindow: toggleMaximize,
      resizeWindow,
