        stat: (path) => fs.promises.stat(path),
        readFile: (path, encoding) => fs.promises.readFile(path, encoding),
        writeFile: (path, data) => fs.promises.writeFile(path, data),
        mkdir: (path, options) => fs.promises.mkdir(path, options),
        rename: (from, to) => fs.promises.rename(from, to),
        remove: (path) => fs.promises.rm(path, { recursive: true, force: true }),
