      h('span', { className: 'window-title' }, item.title),
      h('div', { className: 'window-controls' },
        controlButton(item, 'minimize', 'minimize', 'Minimize'),
        controlButton(item, 'close', 'close', 'Close'))),
      h('div', { className: 'window-content' },
        item.src && h('iframe', {
