        onPointerMove: movePointer,
        onPointerUp: stopPointer,
        onPointerCancel: stopPointer,
      })))),
    h('footer', { className: 'taskbar' },
      h('button', { className: 'new-window', type: 'button', onClick: openWindow }, 'New window'),
      h('button', { className: 'open-app', type: 'button', onClick: promptForApp }, 'Open app'),
      h('nav', { className: 'window-list', 'aria-label': 'Open windows' }, windows.map((item) => h('button', {
        key: item.id,
        className: `taskbar-window${item.minimized ? ' is-minimized' : ''}`,
        type: 'button',
        title: item.title,
        'aria-label': `${item.minimized ? 'Restore' : 'Focus'} ${item.title}`,
        onClick: () => focusWindow(item.id),
      }, item.icon
        ? h('img', { className: 'taskbar-app-icon', src: item.icon, alt: '' })
        : h('span', { className: 'taskbar-window-icon', 'aria-hidden': true }),
      h('span', null, item.title))))));
}

initializeFilesystem().then((fs) => {
  createRoot(document.getElementById('root')).render(h(App, { fs }));
}).catch((error) => {
  document.getElementById('root').textContent = `Filesystem startup failed: ${error.message}`;
});

