    openFileManager('/');
    function handleAppMessage(event) {
      const frame = Array.from(workspaceRef.current.querySelectorAll('iframe')).find((candidate) => candidate.contentWindow === event.source);
      if (!frame || event.data?.channel !== 'slipi-app') return;
