  }, []);

  function promptForApp() {
    const source = window.prompt('Application HTML path or URL', 'WebOS filesystem/Applications/api-example/index.html?--is_windowed&--window_size=640x420');
    if (source) openApp(source);
  }

  function controlButton(item, action, icon, label) {
    return h('button', {
      key: action,
      type: 'button',
      className: action === 'close' ? 'close-control' : '',
      title: label,
      'aria-label': `${label} ${item.title}`,
      onPointerDown: (event) => event.stopPropagation(),
      onClick: () => action === 'close' ? closeWindow(item.id) : minimizeWindow(item.id),
