import React, { useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import Xelite from './Xelite.js';
import { initializeFilesystem, isReadOnlyPath } from './filesystem.js';

const h = React.createElement;

function parseWindowSize(value) {
  const match = /^(\d{2,4})x(\d{2,4})$/i.exec(String(value || '').trim());
  return match ? { width: Number(match[1]), height: Number(match[2]) } : null;
}

function parseDesktopEntry(text) {
  const values = {};
  let inDesktopEntry = false;
  for (const rawLine of text.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#') || line.startsWith(';')) continue;
    if (line.startsWith('[') && line.endsWith(']')) {
      inDesktopEntry = line === '[Desktop Entry]';
      continue;
    }
    if (!inDesktopEntry) continue;
    const separator = line.indexOf('=');
    if (separator <= 0) continue;
    values[line.slice(0, separator).trim()] = line.slice(separator + 1).trim();
  }
  if (!values.Name || !values.Exec) return null;
  return {
    name: values.Name,
    exec: values.Exec,
    icon: values.Icon || 'WebOS filesystem/Icons/nuvola/32x32/apps/applications-accessories.png',
    windowSize: values.WindowSize || undefined,
  };
}

function readDockEntries(fs) {
  try {
    return fs.readdirSync('/Dock')
      .filter((name) => name.toLowerCase().endsWith('.ini'))
      .sort((left, right) => left.localeCompare(right, undefined, { sensitivity: 'base' }))
      .map((file) => ({ file, ...parseDesktopEntry(fs.readFileSync(`/Dock/${file}`, 'utf8')) }))
      .filter((entry) => entry.name && entry.exec);
  } catch {
    return [];
  }
}

function makeWindow(id, area, zIndex, options = {}) {
  const width = Math.min(area.width, Math.max(260, options.width || Math.min(580, area.width - 32)));
  const height = Math.min(area.height, Math.max(210, options.height || Math.min(380, area.height - 32)));
  const offset = (id - 1) * 24;
  return {
    id,
    title: options.title || `Window ${id}`,
    src: options.src || null,
    builtin: options.builtin || null,
    initialPath: options.initialPath || '/',
    icon: options.icon || null,
    isWindowed: options.isWindowed !== false,
    x: Math.max(0, Math.min((area.width - width) / 2 + offset, area.width - Math.min(width, 120))),
    y: Math.max(0, Math.min((area.height - height) / 2 + offset, area.height - 44)),
    width,
    height,
    zIndex,
    minimized: false,
    maximized: false,
    restoreBounds: null,
  };
}

function App({ fs }) {
  const workspaceRef = useRef(null);
  const pointerAction = useRef(null);
  const nextId = useRef(1);
  const nextZ = useRef(1);
  const [windows, setWindows] = useState([]);
  const [dockEntries, setDockEntries] = useState(() => readDockEntries(fs));
  const windowsRef = useRef(windows);
  windowsRef.current = windows;

  function openWindow(options = {}) {
    const area = workspaceRef.current.getBoundingClientRect();
    const id = nextId.current++;
    let appUrl = null;
    let size = parseWindowSize(options.windowSize || (options.width && options.height ? `${options.width}x${options.height}` : ''));
    if (options.src) {
      appUrl = new URL(options.src, window.location.href);
      size = size || parseWindowSize(appUrl.searchParams.get('--window_size'));
      if (options.isWindowed === false) appUrl.searchParams.delete('--is_windowed');
      else appUrl.searchParams.set('--is_windowed', '');
      if (size) appUrl.searchParams.set('--window_size', `${size.width}x${size.height}`);
      else appUrl.searchParams.delete('--window_size');
      appUrl.searchParams.set('--window_id', String(id));
    }
    const segments = appUrl ? appUrl.pathname.split('/').filter(Boolean) : [];
    const file = segments[segments.length - 1] || '';
    const folder = segments[segments.length - 2] || '';
    const title = options.title || (file.toLowerCase() === 'index.html' ? folder : file.replace(/\.[^.]+$/, '')) || `Window ${id}`;
    const item = makeWindow(id, area, nextZ.current++, {
      width: size?.width,
      height: size?.height,
      title,
      src: appUrl?.href,
      builtin: options.builtin,
      initialPath: options.initialPath,
      icon: options.icon ? new URL(options.icon, window.location.href).href : null,
      isWindowed: options.isWindowed,
    });
    item.x = Math.max(0, Math.min(item.x, area.width - Math.min(item.width, 120)));
    item.y = Math.max(0, Math.min(item.y, area.height - 34));
    setWindows((current) => [...current, item]);
    return id;
  }

  function openApp(src, options = {}) {
    if (typeof src !== 'string' || !src.trim()) return null;
    return openWindow({ ...options, src: src.trim() });
  }

  function openFileManager(initialPath = '/') {
    return openWindow({
      builtin: 'xelite',
      initialPath,
      title: 'Xelite File Manager',
      icon: './WebOS filesystem/Icons/nuvola/32x32/apps/system-file-manager.png',
      width: 900,
      height: 560,
    });
  }

  function focusWindow(id) {
    const zIndex = nextZ.current++;
    setWindows((current) => current.map((item) => item.id === id ? { ...item, minimized: false, zIndex } : item));
  }

  function closeWindow(id) {
    setWindows((current) => current.filter((item) => item.id !== id));
  }

  function minimizeWindow(id) {
    setWindows((current) => current.map((item) => item.id === id ? { ...item, minimized: true } : item));
  }

  function toggleMaximize(id) {
    const area = workspaceRef.current.getBoundingClientRect();
    setWindows((current) => current.map((item) => {
      if (item.id !== id) return item;
      if (item.maximized) {
        const bounds = item.restoreBounds;
        return { ...item, ...bounds, maximized: false, restoreBounds: null };
      }
      return {
        ...item,
        restoreBounds: { x: item.x, y: item.y, width: item.width, height: item.height },
        x: 0,
        y: 0,
        width: area.width,
        height: area.height,
        maximized: true,
        minimized: false,
      };
    }));
  }

  function resizeWindow(id, width, height) {
    const area = workspaceRef.current.getBoundingClientRect();
    const nextWidth = Number(width);
    const nextHeight = Number(height);
    if (!Number.isFinite(nextWidth) || !Number.isFinite(nextHeight)) return;
    setWindows((current) => current.map((item) => item.id === id ? {
      ...item,
      width: Math.min(area.width, Math.max(260, nextWidth)),
      height: Math.min(area.height, Math.max(210, nextHeight)),
      maximized: false,
      restoreBounds: null,
    } : item));
  }

  function startPointer(event, item, type) {
    if (event.button !== 0 || item.maximized) return;
    if (type === 'drag' && event.target.closest('button')) return;
    event.stopPropagation();
    focusWindow(item.id);
    pointerAction.current = {
      type,
      id: item.id,
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      x: item.x,
      y: item.y,
      width: item.width,
      height: item.height,
    };
    event.currentTarget.setPointerCapture(event.pointerId);
  }

  function movePointer(event) {
    const action = pointerAction.current;
    const area = workspaceRef.current.getBoundingClientRect();
    if (!action || action.pointerId !== event.pointerId) return;
    setWindows((current) => current.map((item) => {
      if (item.id !== action.id) return item;
      if (action.type === 'drag') {
        return {
          ...item,
          x: Math.max(0, Math.min(area.width - 100, action.x + event.clientX - action.startX)),
          y: Math.max(0, Math.min(area.height - 34, action.y + event.clientY - action.startY)),
        };
      }
      return {
        ...item,
        width: Math.max(Math.min(300, area.width), Math.min(area.width - item.x, action.width + event.clientX - action.startX)),
        height: Math.max(Math.min(210, area.height), Math.min(area.height - item.y, action.height + event.clientY - action.startY)),
      };
    }));
  }

  function stopPointer(event) {
    if (pointerAction.current?.pointerId === event.pointerId) pointerAction.current = null;
  }

  useEffect(() => {
    openFileManager('/');
    const refreshDock = () => setDockEntries(readDockEntries(fs));
    const dockTimer = window.setInterval(refreshDock, 1000);
    function handleAppMessage(event) {
      const frame = Array.from(workspaceRef.current.querySelectorAll('iframe')).find((candidate) => candidate.contentWindow === event.source);
      if (!frame || event.data?.channel !== 'slipi-app') return;
      const id = Number(frame.dataset.windowId);
      const message = event.data;
      if (message.type === 'open-app') openApp(message.src, message.options);
      else if (message.type === 'close') closeWindow(id);
      else if (message.type === 'minimize') minimizeWindow(id);
      else if (message.type === 'maximize') toggleMaximize(id);
      else if (message.type === 'resize') resizeWindow(id, message.width, message.height);
      else if (message.type === 'set-title' && typeof message.title === 'string') {
        setWindows((current) => current.map((item) => item.id === id ? { ...item, title: message.title.slice(0, 120) } : item));
      } else if (message.type === 'set-icon' && typeof message.icon === 'string') {
        setWindows((current) => current.map((item) => item.id === id ? { ...item, icon: message.icon } : item));
      }
    }
    function resizeWindows() {
      const area = workspaceRef.current.getBoundingClientRect();
      setWindows((current) => current.map((item) => item.maximized
        ? { ...item, x: 0, y: 0, width: area.width, height: area.height }
        : {
          ...item,
          x: Math.max(0, Math.min(item.x, area.width - 100)),
          y: Math.max(0, Math.min(item.y, area.height - 34)),
          width: Math.min(item.width, area.width),
          height: Math.min(item.height, area.height),
        }));
    }
    window.addEventListener('message', handleAppMessage);
    window.addEventListener('resize', resizeWindows);
    return () => {
      window.clearInterval(dockTimer);
      window.removeEventListener('message', handleAppMessage);
      window.removeEventListener('resize', resizeWindows);
    };
  }, []);

  function launchDockEntry(entry) {
    if (entry.exec === 'builtin:xelite') {
      openFileManager();
      return;
    }
    const source = entry.exec.startsWith('/')
      ? `WebOS filesystem${entry.exec}`
      : entry.exec.startsWith('WebOS filesystem/') || /^https?:\/\//i.test(entry.exec)
        ? entry.exec
        : `WebOS filesystem/${entry.exec}`;
    openApp(source, { title: entry.name, icon: entry.icon, windowSize: entry.windowSize });
  }

  useEffect(() => {
    window.WebOS = {
      openApp,
      openWindow,
      openFileManager,
      getWindows: () => windowsRef.current.map(({ id, title, x, y, width, height, minimized, maximized }) => ({ id, title, x, y, width, height, minimized, maximized })),
      closeWindow,
      minimizeWindow,
      maximizeWindow: toggleMaximize,
      resizeWindow,
      filesystem: Object.freeze({
        readdir: (path = '/') => fs.promises.readdir(path),
        stat: (path) => fs.promises.stat(path),
        readFile: (path, encoding) => fs.promises.readFile(path, encoding),
        writeFile: (path, data) => isReadOnlyPath(path) ? Promise.reject(new Error('System files are read-only')) : fs.promises.writeFile(path, data),
        mkdir: (path, options) => isReadOnlyPath(path) ? Promise.reject(new Error('System folders are read-only')) : fs.promises.mkdir(path, options),
        rename: (from, to) => isReadOnlyPath(from) || isReadOnlyPath(to) ? Promise.reject(new Error('System files are read-only')) : fs.promises.rename(from, to),
        remove: (path) => isReadOnlyPath(path) ? Promise.reject(new Error('System files are read-only')) : fs.promises.rm(path, { recursive: true, force: true }),
        isReadOnly: isReadOnlyPath,
      }),
    };
    return () => { delete window.WebOS; };
  }, []);

  function controlButton(item, action, icon, label) {
    return h('button', {
      key: action,
      type: 'button',
      className: action === 'close' ? 'close-control' : '',
      title: label,
      'aria-label': `${label} ${item.title}`,
      onPointerDown: (event) => event.stopPropagation(),
      onClick: () => action === 'close' ? closeWindow(item.id) : minimizeWindow(item.id),
    }, h('span', { className: `control-icon icon-${icon}`, 'aria-hidden': true }));
  }

  return h('main', { className: 'desktop' },
    h('section', { className: 'workspace', ref: workspaceRef, 'aria-label': 'Desktop workspace' },
      windows.map((item) => h('section', {
        key: item.id,
        className: `window${item.minimized ? ' window-hidden' : ''}`,
        style: { left: item.x, top: item.y, width: item.width, height: item.height, zIndex: item.zIndex },
        'aria-label': item.title,
        onPointerDown: () => focusWindow(item.id),
      },
      h('header', {
        className: 'window-titlebar',
        onPointerDown: (event) => startPointer(event, item, 'drag'),
        onPointerMove: movePointer,
        onPointerUp: stopPointer,
        onPointerCancel: stopPointer,
        onDoubleClick: () => toggleMaximize(item.id),
      },
      item.icon && h('img', { className: 'window-app-icon', src: item.icon, alt: '' }),
      h('span', { className: 'window-title' }, item.title),
      h('div', { className: 'window-controls' },
        controlButton(item, 'minimize', 'minimize', 'Minimize'),
        controlButton(item, 'close', 'close', 'Close'))),
      h('div', { className: 'window-content' },
        item.src && h('iframe', {
          className: 'app-frame',
          src: item.src,
          title: item.title,
          'data-window-id': item.id,
        }),
        item.builtin === 'xelite' && h(Xelite, { fs, initialPath: item.initialPath })),
      !item.maximized && h('div', {
        className: 'resize-handle',
        role: 'separator',
        'aria-label': `Resize ${item.title}`,
        onPointerDown: (event) => startPointer(event, item, 'resize'),
        onPointerMove: movePointer,
        onPointerUp: stopPointer,
        onPointerCancel: stopPointer,
      })))),
    h('nav', { className: 'app-dock', 'aria-label': 'Application dock' }, dockEntries.map((entry) => h('button', {
      key: entry.file,
      className: 'dock-item',
      type: 'button',
      title: entry.name,
      'aria-label': `Launch ${entry.name}`,
      onClick: () => launchDockEntry(entry),
    }, h('img', {
      src: new URL(entry.icon, window.location.href).href,
      alt: '',
      onError: (event) => { event.currentTarget.src = './WebOS filesystem/Icons/nuvola/32x32/places/folder.png'; },
    }))));
}

initializeFilesystem((complete, total, phase) => {
  const bootStatus = document.querySelector('.boot-status');
  if (bootStatus) bootStatus.textContent = `${phase}: ${Math.floor(complete / total * 100)}%`;
}).then((fs) => {
  createRoot(document.getElementById('root')).render(h(App, { fs }));
}).catch((error) => {
  document.getElementById('root').textContent = `Filesystem startup failed: ${error.message}`;
});

const systemDirectories = [
  '/Application files',
  '/Applications',
  '/Dock',
  '/Linux files',
  '/Public',
  '/Trash',
];
const readOnlyRoots = ['/Application files', '/Applications', '/Icons', '/Linux files'];
const previousSeedMarkers = ['/.webos-filesystem-seeded-v1', '/.webos-filesystem-seeded-v2'];
const seedMarker = '/.webos-filesystem-seeded-v3';

let initialization;

export function normalizeFilesystemPath(path) {
  const parts = [];
  for (const part of String(path).replace(/\\/g, '/').split('/')) {
    if (!part || part === '.') continue;
    if (part === '..') parts.pop();
    else parts.push(part);
  }
  return `/${parts.join('/')}`;
}

export function isReadOnlyPath(path) {
  const normalized = normalizeFilesystemPath(path);
  return normalized === '/' || normalized === '/app-api.js' || readOnlyRoots.some((root) => normalized === root || normalized.startsWith(`${root}/`));
}

function ensureDirectory(fs, path, mkdirSync = fs.mkdirSync.bind(fs)) {
  let current = '';
  for (const part of path.split('/').filter(Boolean)) {
    current += `/${part}`;
    if (!fs.existsSync(current)) mkdirSync(current);
  }
}

function removePath(fs, path) {
  if (!path || path === '/') throw new Error('Cannot remove the filesystem root');
  const stat = fs.statSync(path);
  if (stat.isDirectory()) {
    for (const name of fs.readdirSync(path)) removePath(fs, `${path.replace(/\/$/, '')}/${name}`);
    fs.rmdirSync(path);
  } else {
    fs.unlinkSync(path);
  }
}

function callbackPromise(fs, method, args) {
  return new Promise((resolve, reject) => {
    fs[method](...args, (error, result) => error ? reject(error) : resolve(result));
  });
}

function waitForMirror(fs) {
  const mirror = typeof fs.getRootFS === 'function' ? fs.getRootFS() : fs;
  if (!mirror || !Array.isArray(mirror._queue)) return Promise.resolve();
  return new Promise((resolve) => {
    function checkQueue() {
      if (!mirror._queueRunning && mirror._queue.length === 0) resolve();
      else window.setTimeout(checkQueue, 20);
    }
    checkQueue();
  });
}

async function seedBundledTree(fs, Buffer, onProgress) {
  if (fs.existsSync(seedMarker)) return;
  const manifestResponse = await fetch(new URL('./filesystem-manifest.json', import.meta.url));
  if (!manifestResponse.ok) throw new Error(`Could not load filesystem manifest (${manifestResponse.status})`);
  const { files } = await manifestResponse.json();
  const sourceBase = new URL('./WebOS%20filesystem/', import.meta.url);
  let cursor = 0;
  let complete = 0;
  const concurrency = 12;

  async function worker() {
    while (cursor < files.length) {
      const relativePath = files[cursor++];
      const target = `/${relativePath}`;
      if (!fs.existsSync(target)) {
        const source = new URL(relativePath.split('/').map(encodeURIComponent).join('/'), sourceBase);
        const response = await fetch(source);
        if (!response.ok) throw new Error(`Could not seed ${relativePath} (${response.status})`);
        const parent = target.slice(0, target.lastIndexOf('/')) || '/';
        ensureDirectory(fs, parent);
        fs.writeFileSync(target, Buffer.from(await response.arrayBuffer()));
      }
      complete++;
      if (complete % 40 === 0 || complete === files.length) onProgress?.(complete, files.length, 'Copying WebOS filesystem');
    }
  }

  await Promise.all(Array.from({ length: Math.min(concurrency, files.length) }, worker));
  onProgress?.(files.length, files.length, 'Saving files to IndexedDB');
  await waitForMirror(fs);
  fs.writeFileSync(seedMarker, 'done');
  await waitForMirror(fs);
}

export function initializeFilesystem(onProgress) {
  if (!initialization) {
    initialization = (async () => {
      await new Promise((resolve, reject) => {
        window.BrowserFS.configure({
          fs: 'AsyncMirror',
          options: {
            sync: { fs: 'InMemory' },
            async: { fs: 'IndexedDB', options: { storeName: 'slipi-os-browserfs' } },
          },
        }, (error) => error ? reject(error) : resolve());
      });
      const fs = window.BrowserFS.BFSRequire('fs');
      const BrowserBuffer = window.BrowserFS.BFSRequire('buffer').Buffer;
      const baseMkdirSync = fs.mkdirSync.bind(fs);
      if (fs.existsSync('/Icons')) removePath(fs, '/Icons');
      for (const marker of previousSeedMarkers) {
        if (fs.existsSync(marker)) fs.unlinkSync(marker);
      }
      for (const path of systemDirectories) ensureDirectory(fs, path, baseMkdirSync);
      fs.mkdirSync = (path, options) => options && typeof options === 'object' && options.recursive
        ? ensureDirectory(fs, path, baseMkdirSync)
        : baseMkdirSync(path, typeof options === 'number' ? options : undefined);
      fs.rmSync = (path) => removePath(fs, path);
      fs.Buffer = BrowserBuffer;
      fs.promises = {
        readdir: (path = '/') => callbackPromise(fs, 'readdir', [path]),
        stat: (path) => callbackPromise(fs, 'stat', [path]),
        readFile: (path, encoding) => callbackPromise(fs, 'readFile', encoding ? [path, encoding] : [path]),
        writeFile: (path, data, encoding) => {
          const contents = data instanceof Uint8Array && !(data instanceof BrowserBuffer) ? BrowserBuffer.from(data) : data;
          return callbackPromise(fs, 'writeFile', encoding ? [path, contents, encoding] : [path, contents]);
        },
        mkdir: (path) => new Promise((resolve, reject) => {
          try { ensureDirectory(fs, path); resolve(); } catch (error) { reject(error); }
        }),
        rename: (from, to) => callbackPromise(fs, 'rename', [from, to]),
        rm: (path) => Promise.resolve().then(() => removePath(fs, path)).then(() => waitForMirror(fs)),
        flush: () => waitForMirror(fs),
      };
      await seedBundledTree(fs, BrowserBuffer, onProgress);
      return fs;
    })();
  }
  return initialization;
}

import React, { useEffect, useMemo, useRef, useState } from 'react';
import { isReadOnlyPath, normalizeFilesystemPath } from './filesystem.js';

const h = React.createElement;
const iconRoot = './WebOS filesystem/Icons/nuvola/32x32';
const quickLocations = [
  { name: 'Root', path: '/', icon: 'places/desktop.png' },
  { name: 'Public', path: '/Public', icon: 'places/user-home.png' },
  { name: 'Applications', path: '/Applications', icon: 'apps/applications-accessories.png' },
  { name: 'Dock', path: '/Dock', icon: 'places/folder.png' },
  { name: 'Application files', path: '/Application files', icon: 'places/folder.png' },
  { name: 'Linux files', path: '/Linux files', icon: 'devices/drive-harddisk.png' },
];
const textExtensions = new Set(['.txt', '.md', '.html', '.htm', '.js', '.css', '.json', '.xml', '.csv', '.log', '.sh', '.ini', '.cfg', '.yaml', '.yml']);

function joinPath(base, name) {
  return `${base === '/' ? '' : base}/${name}`.replace(/\/{2,}/g, '/');
}

function parentPath(path) {
  if (path === '/') return '/';
  const parts = path.split('/').filter(Boolean);
  parts.pop();
  return parts.length ? `/${parts.join('/')}` : '/';
}

function fileType(name, isDirectory) {
  if (isDirectory) return 'Folder';
  const extension = name.includes('.') ? name.slice(name.lastIndexOf('.')).toLowerCase() : '';
  return extension ? `${extension.slice(1).toUpperCase()} file` : 'File';
}

function fileIcon(entry) {
  if (entry.isDirectory) return `${iconRoot}/places/folder.png`;
  const extension = entry.name.includes('.') ? entry.name.slice(entry.name.lastIndexOf('.')).toLowerCase() : '';
  const names = {
    '.html': 'text-html.png', '.htm': 'text-html.png', '.js': 'application-javascript.png',
    '.css': 'text-css.png', '.json': 'application-json.png', '.pdf': 'application-pdf.png',
    '.png': 'image-png.png', '.jpg': 'image-jpeg.png', '.jpeg': 'image-jpeg.png',
    '.svg': 'image-svg+xml.png', '.zip': 'application-zip.png', '.gz': 'application-gzip.png',
    '.txt': 'text-plain.png', '.md': 'text-markdown.png',
  };
  return `${iconRoot}/mimetypes/${names[extension] || 'application-octet-stream.png'}`;
}

function formatSize(bytes) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function ToolButton({ icon, label, onClick, disabled }) {
  return h('button', { className: 'xelite-tool', type: 'button', title: label, 'aria-label': label, onClick, disabled },
    h('img', {
      src: `${iconRoot}/actions/${icon}.png`,
      alt: '',
      onError: (event) => { event.currentTarget.src = `${iconRoot}/actions/help-contents.png`; },
    }));
}

export default function Xelite({ fs, initialPath = '/' }) {
  const [path, setPath] = useState(initialPath);
  const [pathDraft, setPathDraft] = useState(initialPath);
  const [entries, setEntries] = useState([]);
  const [selectedPath, setSelectedPath] = useState(null);
  const [filter, setFilter] = useState('');
  const [editor, setEditor] = useState(null);
  const [status, setStatus] = useState('Ready');
  const [history, setHistory] = useState([initialPath]);
  const [historyIndex, setHistoryIndex] = useState(0);
  const [sort, setSort] = useState({ key: 'name', direction: 1 });
  const filesInput = useRef(null);
  const folderInput = useRef(null);

  function refresh(nextPath = path) {
    try {
      const directory = nextPath === '/' ? '/' : nextPath.replace(/\/$/, '');
      const items = fs.readdirSync(directory).filter((name) => !(directory === '/' && name.startsWith('.webos-filesystem-seeded-v'))).map((name) => {
        const fullPath = joinPath(directory, name);
        const info = fs.statSync(fullPath);
        return { name, path: fullPath, isDirectory: info.isDirectory(), size: Number(info.size) || 0, mtime: Number(info.mtimeMs) || 0 };
      });
      setEntries(items);
      setPath(directory);
      setPathDraft(directory);
      setSelectedPath((selected) => items.some((item) => item.path === selected) ? selected : null);
      setStatus(`${items.length} item${items.length === 1 ? '' : 's'}`);
    } catch (error) {
      setStatus(error.message || 'Unable to open folder');
    }
  }

  function navigate(nextPath, addHistory = true) {
    const normalized = normalizeFilesystemPath(nextPath);
    refresh(normalized);
    if (addHistory && normalized !== path) {
      setHistory((current) => [...current.slice(0, historyIndex + 1), normalized]);
      setHistoryIndex((current) => current + 1);
    }
  }

  useEffect(() => { refresh(initialPath); }, []);

  const visibleEntries = useMemo(() => {
    const query = filter.trim().toLowerCase();
    return entries
      .filter((entry) => !query || entry.name.toLowerCase().includes(query))
      .sort((left, right) => {
        if (left.isDirectory !== right.isDirectory) return left.isDirectory ? -1 : 1;
        const result = sort.key === 'size' ? left.size - right.size : left.name.localeCompare(right.name, undefined, { numeric: true, sensitivity: 'base' });
        return result * sort.direction;
      });
  }, [entries, filter, sort]);

  function selectedEntry() {
    return entries.find((entry) => entry.path === selectedPath) || null;
  }

  async function createFile() {
    if (isReadOnlyPath(path)) { setStatus('This system folder is read-only'); return; }
    const name = window.prompt('New file name');
    if (!name || name.includes('/') || name === '.' || name === '..') return;
    const target = joinPath(path, name);
    try {
      fs.writeFileSync(target, '');
      await fs.promises.flush();
      refresh();
      setSelectedPath(target);
      setEditor({ path: target, name, content: '' });
    } catch (error) { window.alert(error.message); }
  }

  async function createFolder() {
    if (isReadOnlyPath(path)) { setStatus('This system folder is read-only'); return; }
    const name = window.prompt('New folder name');
    if (!name || name.includes('/') || name === '.' || name === '..') return;
    try { fs.mkdirSync(joinPath(path, name)); await fs.promises.flush(); refresh(); }
    catch (error) { window.alert(error.message); }
  }

  async function renameSelected() {
    const item = selectedEntry();
    if (!item || isReadOnlyPath(item.path)) { setStatus('This system item is read-only'); return; }
    const name = window.prompt('Rename item', item.name);
    if (!name || name.includes('/') || name === item.name) return;
    try { fs.renameSync(item.path, joinPath(path, name)); await fs.promises.flush(); refresh(); }
    catch (error) { window.alert(error.message); }
  }

  async function deleteSelected() {
    const item = selectedEntry();
    if (!item) return;
    if (isReadOnlyPath(item.path)) { setStatus('This system item is read-only'); return; }
    if (!window.confirm(`Permanently delete ${item.name}?`)) return;
    try {
      fs.rmSync(item.path, { recursive: true, force: true });
      await fs.promises.flush();
      refresh();
    } catch (error) { window.alert(error.message); }
  }

  async function openSelected(item) {
    if (item.isDirectory) {
      navigate(item.path);
      return;
    }
    const extension = item.name.includes('.') ? item.name.slice(item.name.lastIndexOf('.')).toLowerCase() : '';
    if (extension === '.html' && item.path.startsWith('/Applications/')) {
      const source = new URL(`./WebOS filesystem${item.path}`, window.location.href);
      try {
        const response = await fetch(source, { method: 'HEAD' });
        if (response.ok && window.WebOS?.openApp) {
          window.WebOS.openApp(source.href, { title: item.name });
          return;
        }
      } catch { }
    }
    if (!textExtensions.has(extension)) {
      setStatus(`${item.name} is not a supported text document`);
      return;
    }
    try { setEditor({ path: item.path, name: item.name, content: fs.readFileSync(item.path, 'utf8') }); }
    catch (error) { window.alert(error.message); }
  }

  function navigateHistory(direction) {
    const nextIndex = historyIndex + direction;
    if (nextIndex < 0 || nextIndex >= history.length) return;
    setHistoryIndex(nextIndex);
    refresh(history[nextIndex]);
  }

  async function saveEditor() {
    if (isReadOnlyPath(editor.path)) { setStatus('This system file is read-only'); return; }
    try {
      fs.writeFileSync(editor.path, editor.content, 'utf8');
      await fs.promises.flush();
      setEditor(null);
      refresh();
      setStatus(`Saved ${editor.name}`);
    } catch (error) { window.alert(error.message); }
  }

  async function importFiles(event, isFolder) {
    const files = Array.from(event.target.files || []);
    if (!files.length) return;
    if (!isFolder && isReadOnlyPath(path)) {
      setStatus('Import into Public or Trash; system folders are read-only');
      event.target.value = '';
      return;
    }
    setStatus(`Importing ${files.length} files...`);
    let imported = 0;
    let cursor = 0;
    async function worker() {
      while (cursor < files.length) {
        const file = files[cursor++];
        const relative = isFolder && file.webkitRelativePath
          ? file.webkitRelativePath.split('/').slice(1).join('/')
          : file.name;
        const parts = relative.split('/').filter((part) => part && part !== '.');
        if (!parts.length || parts.includes('..')) continue;
        const target = isFolder ? joinPath('/Public', parts.join('/')) : joinPath(path, parts.join('/'));
        try {
          fs.mkdirSync(parentPath(target), { recursive: true });
          await fs.promises.writeFile(target, fs.Buffer.from(await file.arrayBuffer()));
          imported++;
        } catch (error) {
          setStatus(`Could not import ${file.name}: ${error.message}`);
        }
      }
    }
    await Promise.all(Array.from({ length: Math.min(12, files.length) }, worker));
    await fs.promises.flush();
    event.target.value = '';
    refresh(isFolder ? '/Public' : path);
    setStatus(`Imported ${imported} of ${files.length} files`);
  }

  function downloadSelected() {
    const item = selectedEntry();
    if (!item || item.isDirectory) return;
    try {
      const content = fs.readFileSync(item.path);
      const url = URL.createObjectURL(new Blob([content]));
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = item.name;
      anchor.click();
      URL.revokeObjectURL(url);
    } catch (error) { window.alert(error.message); }
  }

  function sortBy(key) {
    setSort((current) => ({ key, direction: current.key === key ? -current.direction : 1 }));
  }

  function locationButton(location) {
    return h('button', {
      key: location.path,
      className: `xelite-location${path === location.path ? ' is-current' : ''}`,
      type: 'button',
      onClick: () => navigate(location.path),
    }, h('img', { src: `${iconRoot}/${location.icon}`, alt: '' }), h('span', null, location.name));
  }

  const directoryReadOnly = isReadOnlyPath(path);
  const selection = selectedEntry();
  const selectionReadOnly = !selection || isReadOnlyPath(selection.path);

  const toolbar = h('div', { className: 'xelite-toolbar' },
    h(ToolButton, { icon: 'go-previous', label: 'Back', onClick: () => navigateHistory(-1), disabled: historyIndex === 0 }),
    h(ToolButton, { icon: 'go-next', label: 'Forward', onClick: () => navigateHistory(1), disabled: historyIndex >= history.length - 1 }),
    h(ToolButton, { icon: 'go-home', label: 'Home', onClick: () => navigate('/') }),
    h(ToolButton, { icon: 'go-up', label: 'Up one folder', onClick: () => navigate(parentPath(path)) }),
    h(ToolButton, { icon: 'view-refresh', label: 'Refresh', onClick: () => refresh() }),
    h('span', { className: 'xelite-toolbar-divider' }),
    h(ToolButton, { icon: 'document-new', label: 'New file', onClick: createFile, disabled: directoryReadOnly }),
    h(ToolButton, { icon: 'folder-new', label: 'New folder', onClick: createFolder, disabled: directoryReadOnly }),
    h(ToolButton, { icon: 'document-open', label: 'Import files', onClick: () => filesInput.current.click(), disabled: directoryReadOnly }),
    h(ToolButton, { icon: 'folder-new', label: 'Import folder to Public', onClick: () => folderInput.current.click() }),
    h(ToolButton, { icon: 'document-save', label: 'Download selected file', onClick: downloadSelected, disabled: !selection || selection.isDirectory }),
    h(ToolButton, { icon: 'document-save-as', label: 'Rename selected item', onClick: renameSelected, disabled: selectionReadOnly }),
    h(ToolButton, { icon: 'window-close', label: 'Delete selected item', onClick: deleteSelected, disabled: selectionReadOnly }),
    h('input', { ref: filesInput, className: 'xelite-file-input', type: 'file', multiple: true, onChange: (event) => importFiles(event, false) }),
    h('input', { ref: folderInput, className: 'xelite-file-input', type: 'file', multiple: true, webkitdirectory: '', onChange: (event) => importFiles(event, true) }));

  const address = h('form', { className: 'xelite-address', onSubmit: (event) => { event.preventDefault(); navigate(pathDraft); } },
    h('label', { htmlFor: 'xelite-path' }, 'Location:'),
    h('input', { id: 'xelite-path', value: pathDraft, onChange: (event) => setPathDraft(event.target.value), spellCheck: false }),
    h('button', { type: 'submit' }, 'Go'),
    h('input', { className: 'xelite-search', value: filter, onChange: (event) => setFilter(event.target.value), placeholder: 'Filter files', 'aria-label': 'Filter files' }));

  const sidebar = h('aside', { className: 'xelite-sidebar' },
    h('h2', null, 'Devices'),
    h('div', { className: 'xelite-location-list' }, quickLocations.map(locationButton)),
    h('h2', { className: 'xelite-actions-heading' }, 'Actions'),
    h('button', { className: 'xelite-action', type: 'button', onClick: createFile, disabled: directoryReadOnly }, 'New file'),
    h('button', { className: 'xelite-action', type: 'button', onClick: createFolder, disabled: directoryReadOnly }, 'New folder'),
    h('button', { className: 'xelite-action', type: 'button', onClick: () => folderInput.current.click() }, 'Import folder to Public'));

  const table = h('table', { className: 'xelite-table' },
    h('thead', null, h('tr', null,
      h('th', { scope: 'col', onClick: () => sortBy('name') }, 'File'),
      h('th', { scope: 'col' }, 'Type'),
      h('th', { scope: 'col', className: 'size-column', onClick: () => sortBy('size') }, 'Size'))),
    h('tbody', null, visibleEntries.map((entry) => h('tr', {
      key: entry.path,
      className: selectedPath === entry.path ? 'is-selected' : '',
      title: isReadOnlyPath(entry.path) ? 'Read-only system item' : entry.name,
      onClick: () => setSelectedPath(entry.path),
      onDoubleClick: () => openSelected(entry),
    },
    h('td', null, h('span', { className: 'xelite-file-name' }, h('img', {
      src: fileIcon(entry),
      alt: '',
      onError: (event) => { event.currentTarget.src = `${iconRoot}/mimetypes/application-octet-stream.png`; },
    }), h('span', null, entry.name))),
    h('td', null, fileType(entry.name, entry.isDirectory)),
    h('td', { className: 'size-column' }, entry.isDirectory ? '<DIR>' : formatSize(entry.size))))));

  const body = h('div', { className: 'xelite-body' }, sidebar, h('div', { className: 'xelite-file-pane' }, table));
  const statusBar = h('div', { className: 'xelite-status' }, `${path}  |  ${status}${directoryReadOnly ? '  |  Read-only' : ''}`);
  const editorDialog = editor && h('div', { className: 'xelite-editor-backdrop' },
    h('section', { className: 'xelite-editor', role: 'dialog', 'aria-modal': true, 'aria-label': `Edit ${editor.name}` },
      h('header', null, h('span', null, editor.name), h('button', { type: 'button', onClick: () => setEditor(null), 'aria-label': 'Close editor' }, '×')),
      h('textarea', { value: editor.content, readOnly: isReadOnlyPath(editor.path), spellCheck: false, onChange: (event) => setEditor((current) => ({ ...current, content: event.target.value })) }),
      h('footer', null,
        h('button', { type: 'button', onClick: saveEditor, disabled: isReadOnlyPath(editor.path) }, 'Save'),
        h('button', { type: 'button', onClick: () => setEditor(null) }, 'Cancel'))));

  return h('div', { className: 'xelite', onKeyDown: (event) => {
    if (event.key === 'F5') { event.preventDefault(); refresh(); }
    if (event.key === 'Backspace' && event.target.tagName !== 'INPUT' && event.target.tagName !== 'TEXTAREA') navigate(parentPath(path));
    if (event.key === 'Delete' && event.target.tagName !== 'INPUT' && event.target.tagName !== 'TEXTAREA') deleteSelected();
  } }, toolbar, address, body, statusBar, editorDialog);
}

:root { font-family: Tahoma, Arial, sans-serif; color: #111; background: #c0c0c0; }
